import java.util.ArrayDeque;
import java.util.Deque;

public class BrowserHistory {
    private String currentPage;
    private final Deque<String> backStack = new ArrayDeque<>();
    private final Deque<String> forwardStack = new ArrayDeque<>();

    public BrowserHistory(String homepage) {
        this.currentPage = homepage;
    }

    public void visit(String url) {
        backStack.push(currentPage);
        forwardStack.clear(); // Visiting a new page clears forward history
        currentPage = url;
    }

    public String back() {
        if (!backStack.isEmpty()) {
            forwardStack.push(currentPage);
            currentPage = backStack.pop();
        }
        return currentPage;
    }

    public String forward() {
        if (!forwardStack.isEmpty()) {
            backStack.push(currentPage);
            currentPage = forwardStack.pop();
        }
        return currentPage;
    }

    public static void main(String[] args) {
        BrowserHistory browser = new BrowserHistory("google.com");
        browser.visit("github.com");
        browser.visit("stackoverflow.com");

        System.out.println("Current: " + browser.currentPage);     // stackoverflow.com
        System.out.println("Back:    " + browser.back());            // github.com
        System.out.println("Back:    " + browser.back());            // google.com
        System.out.println("Forward: " + browser.forward());         // github.com
    }
}

